// @generated by tilo-app; locale registry.
// Edit Fluent catalogs under locales/; tilo-app maintains this registry.
// tilo-app:locale=de-DE
// tilo-app:locale=en-US

ui::embedded_catalog!(pub static CATALOG, ["de-DE", "en-US"]);

/// German is one of the languages the app ships, and it reads in German: the
/// copy comes from `locales/de-DE.ftl`, never from the English source
/// catalogue beside it.
#[cfg(test)]
mod german_window {
    #[test]
    fn a_german_window_reads_the_catalogue() {
        let catalog = &super::CATALOG;
        assert!(
            catalog.languages().contains(&"de-DE"),
            "the app ships German among {:?}",
            catalog.languages()
        );
        catalog.set_locale("de-DE");
        assert_eq!(
            catalog.t("print-centre-loading"),
            "Druckzentrale wird geladen"
        );
        catalog.set_locale("en-US");
        assert_eq!(catalog.t("print-centre-loading"), "Loading Print Centre");
    }
}
